package com.rustybank.legacy;

public class MoneyUtil {
    public static long parseToCents(String amount) {
        if (amount == null) throw new IllegalArgumentException("INVALID AMOUNT");
        double d = Double.parseDouble(amount.trim());
        if (d <= 0) throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        return Math.round(d * 100);
    }

    public static String format(long cents) {
        return (cents / 100) + "." + String.format("%02d", Math.abs(cents % 100));
    }
}
